using System;using System.Linq;using Mono.Cecil;using Mono.Cecil.Cil;
class VerifyTexturePaths {static void Main(string[] a){using(var x=AssemblyDefinition.ReadAssembly(a[0])){var t=x.MainModule.GetType("TextureReplacer.BepInExPlugin");int selected=0,total=0;foreach(var m in t.Methods.Where(m=>m.Name=="CacheCardDataAtStart"||m.Name=="LoadCardNames"))foreach(var i in m.Body.Instructions){if(i.OpCode!=OpCodes.Ldstr||!new[]{"\\cards","\\"}.Contains(i.Operand as string))continue;total++;var mr=i.Next.Operand as MethodReference;if(i.Next.OpCode==OpCodes.Call&&mr!=null&&mr.FullName=="System.String TCG.NativeCompatibility.PathLiterals::Select(System.String)")selected++;}if(total!=5||selected!=5)throw new Exception("Five filesystem literals need platform dispatch; total="+total+", selected="+selected);Console.WriteLine("5 narrowly selected filesystem literal sites verified");}}}
